 [CK('echo "svc inventory"', 'svc', 'Start: `echo "svc inventory" > svc-inventory.md`.'),
  CK('wc -l svc-inventory.md', 'svc-inventory.md', 'Verify coverage: `wc -l svc-inventory.md`.')],
